     1→/**
     2→ * FreeWire - 백엔드 API 서버
     3→ * POST /compile  → 그래프 JSON → .free 코드
     4→ * POST /execute  → 그래프 JSON → HTML/CSS/JS
     5→ * GET  /preview/:id → 브라우저 미리보기
     6→ * GET  /health
     7→ */
     8→
     9→const http = require('http');
    10→const { Graph }          = require('../core/graph');
    11→const { GraphCompiler }  = require('../compiler/graph-compiler');
    12→const { FreeExecutor }   = require('./free-executor');
    13→const { aiGenerateGraph } = require('./ai-graph-generator');
    14→const { getBridge }      = require('../core/plugin-bridge');
    15→
    16→const PORT = process.env.FREEWIRE_PORT || 4010;
    17→
    18→const compiler = new GraphCompiler();
    19→const executor = new FreeExecutor();
    20→
    21→// 플러그인 시스템 초기화 (서버 시작 시 1회)
    22→getBridge();
    23→
    24→// 미리보기 캐시 { id → { html, css, js, createdAt } }
    25→const previewCache = new Map();
    26→
    27→// ─── 라우터 ─────────────────────────────────────────────────────
    28→const ROUTES = {
    29→  'GET /health':       handleHealth,
    30→  'GET /api/nodes':    handleNodeTypes,
    31→  'POST /api/compile': handleCompile,
    32→  'POST /api/execute': handleExecute,
    33→  'POST /api/preview': handlePreviewCreate,
    34→  'POST /api/ai-generate': handleAIGenerate,
    35→};
    36→
    37→function router(req, res) {
    38→  const key = `${req.method} ${req.url.split('?')[0]}`;
    39→
    40→  // GET /preview/:id
    41→  if (req.method === 'GET' && req.url.startsWith('/preview/')) {
    42→    return handlePreviewGet(req, res);
    43→  }
    44→
    45→  const handler = ROUTES[key];
    46→  if (handler) return handler(req, res);
    47→
    48→  send(res, 404, { error: `라우트 없음: ${key}` });
    49→}
    50→
    51→// ─── 핸들러 ─────────────────────────────────────────────────────
    52→
    53→function handleHealth(req, res) {
    54→  send(res, 200, {
    55→    status: 'ok',
    56→    service: 'FreeWire API',
    57→    version: '0.1.0',
    58→    uptime: process.uptime().toFixed(1) + 's',
    59→  });
    60→}
    61→
    62→function handleNodeTypes(req, res) {
    63→  const { NODE_TYPE_DEFS } = require('../core/node-types-index');
    64→  const nodeTypes = { ...NODE_TYPE_DEFS };
    65→
    66→  // stdlib 카테고리 추가 (PluginBridge가 준비된 경우)
    67→  const bridge = getBridge();
    68→  const stdlibCategory = bridge.getPaletteCategory();
    69→  if (stdlibCategory) {
    70→    nodeTypes.stdlib = stdlibCategory;
    71→  }
    72→
    73→  send(res, 200, { nodeTypes });
    74→}
    75→
    76→async function handleCompile(req, res) {
    77→  let body;
    78→  try { body = await readBody(req); }
    79→  catch (e) { return send(res, 400, { error: 'JSON 파싱 실패: ' + e.message }); }
    80→
    81→  const { graph } = body;
    82→  if (!graph) return send(res, 400, { error: 'body.graph 필수' });
    83→
    84→  try {
    85→    const result = compiler.compile(graph);
    86→    send(res, 200, {
    87→      code:     result.code,
    88→      errors:   result.errors,
    89→      warnings: result.warnings,
    90→    });
    91→  } catch (e) {
    92→    send(res, 500, { error: '컴파일 실패: ' + e.message });
    93→  }
    94→}
    95→
    96→async function handleExecute(req, res) {
    97→  let body;
    98→  try { body = await readBody(req); }
    99→  catch (e) { return send(res, 400, { error: 'JSON 파싱 실패: ' + e.message }); }
   100→
   101→  const { graph } = body;
   102→  if (!graph) return send(res, 400, { error: 'body.graph 필수' });
   103→
   104→  try {
   105→    const compiled = compiler.compile(graph);
   106→    if (compiled.errors.length > 0) {
   107→      return send(res, 422, { error: '컴파일 오류', details: compiled.errors });
   108→    }
   109→    const output = executor.execute(compiled.code, graph);
   110→    send(res, 200, output);
   111→  } catch (e) {
   112→    send(res, 500, { error: '실행 실패: ' + e.message });
   113→  }
   114→}
   115→
   116→async function handlePreviewCreate(req, res) {
   117→  let body;
   118→  try { body = await readBody(req); }
   119→  catch (e) { return send(res, 400, { error: 'JSON 파싱 실패: ' + e.message }); }
   120→
   121→  const { graph } = body;
   122→  if (!graph) return send(res, 400, { error: 'body.graph 필수' });
   123→
   124→  try {
   125→    const compiled = compiler.compile(graph);
   126→    if (compiled.errors.length > 0) {
   127→      return send(res, 422, { error: '컴파일 오류', details: compiled.errors });
   128→    }
   129→    const output = executor.execute(compiled.code, graph);
   130→    const id     = `preview-${Date.now()}`;
   131→
   132→    // 캐시 최대 100개 제한 (LRU: 가장 오래된 항목 제거)
   133→    if (previewCache.size >= 100) {
   134→      const oldest = previewCache.keys().next().value;
   135→      previewCache.delete(oldest);
   136→    }
   137→    previewCache.set(id, { ...output, createdAt: Date.now() });
   138→
   139→    // 캐시 1시간 TTL
   140→    setTimeout(() => previewCache.delete(id), 3600_000);
   141→
   142→    send(res, 201, { previewId: id, url: `/preview/${id}` });
   143→  } catch (e) {
   144→    send(res, 500, { error: '미리보기 생성 실패: ' + e.message });
   145→  }
   146→}
   147→
   148→
   149→async function handleAIGenerate(req, res) {
   150→  let body;
   151→  try { body = await readBody(req); }
   152→  catch (e) { return send(res, 400, { error: 'JSON 파싱 실패: ' + e.message }); }
   153→
   154→  const { prompt, apiKey } = body;
   155→  if (!prompt) return send(res, 400, { error: 'body.prompt 필수' });
   156→
   157→  try {
   158→    const result = await aiGenerateGraph(prompt, apiKey);
   159→    send(res, 200, result);
   160→  } catch (e) {
   161→    send(res, 500, { error: 'AI 생성 실패: ' + e.message });
   162→  }
   163→}
   164→
   165→function handlePreviewGet(req, res) {
   166→  const id = req.url.replace('/preview/', '').split('?')[0];
   167→  const preview = previewCache.get(id);
   168→
   169→  if (!preview) {
   170→    res.writeHead(404, { 'Content-Type': 'text/html' });
   171→    res.end('<h1>미리보기 없음 (만료되었거나 잘못된 ID)</h1>');
   172→    return;
   173→  }
   174→
   175→  const html = buildPreviewHtml(preview);
   176→  res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
   177→  res.end(html);
   178→}
   179→
   180→// ─── 유틸 ────────────────────────────────────────────────────────
   181→
   182→function buildPreviewHtml({ html, css, js }) {
   183→  return `<!DOCTYPE html>
   184→<html lang="ko">
   185→<head>
   186→  <meta charset="UTF-8">
   187→  <meta name="viewport" content="width=device-width, initial-scale=1.0">
   188→  <title>FreeWire 미리보기</title>
   189→  <style>
   190→    * { box-sizing: border-box; margin: 0; padding: 0; }
   191→    body { font-family: system-ui, sans-serif; padding: 24px; background: #f9fafb; }
   192→    .freewire-badge {
   193→      position: fixed; bottom: 12px; right: 12px;
   194→      background: #6366f1; color: white;
   195→      padding: 4px 10px; border-radius: 999px;
   196→      font-size: 12px; opacity: 0.85;
   197→    }
   198→    ${css || ''}
   199→  </style>
   200→</head>
   201→<body>
   202→  <div id="app">${html || '<p style="color:#999">내용 없음</p>'}</div>
   203→  <div class="freewire-badge">⚡ FreeWire</div>
   204→  <script>${js || ''}</script>
   205→</body>
   206→</html>`;
   207→}
   208→
   209→function send(res, status, data) {
   210→  const body = JSON.stringify(data);
   211→  res.writeHead(status, {
   212→    'Content-Type':  'application/json',
   213→    'Access-Control-Allow-Origin': '*',
   214→    'Access-Control-Allow-Headers': 'Content-Type',
   215→  });
   216→  res.end(body);
   217→}
   218→
   219→function readBody(req) {
   220→  return new Promise((resolve, reject) => {
   221→    let data = '';
   222→    req.on('data', chunk => { data += chunk; if (data.length > 1_000_000) reject(new Error('너무 큰 요청')); });
   223→    req.on('end',  () => { try { resolve(JSON.parse(data)); } catch (e) { reject(e); } });
   224→    req.on('error', reject);
   225→  });
   226→}
   227→
   228→// ─── 서버 시작 ───────────────────────────────────────────────────
   229→const server = http.createServer((req, res) => {
   230→  if (req.method === 'OPTIONS') {
   231→    res.writeHead(204, { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Headers': 'Content-Type', 'Access-Control-Allow-Methods': 'GET,POST' });
   232→    return res.end();
   233→  }
   234→  router(req, res);
   235→});
   236→
   237→if (require.main === module) {
   238→  server.listen(PORT, () => {
   239→    console.log(`\n⚡ FreeWire API 서버 시작`);
   240→    console.log(`   http://localhost:${PORT}/health`);
   241→    console.log(`   POST http://localhost:${PORT}/api/compile`);
   242→    console.log(`   POST http://localhost:${PORT}/api/execute`);
   243→    console.log(`   POST http://localhost:${PORT}/api/preview\n`);
   244→  });
   245→}
   246→
   247→module.exports = { server, previewCache };
   248→

