     1→/**
     2→ * FreeWire Phase 6 - WebSocket 실시간 협업 서버
     3→ * 여러 클라이언트가 같은 그래프를 동시에 편집
     4→ *
     5→ * 프로토콜:
     6→ *   client → server: { type, roomId, payload }
     7→ *   server → client: { type, roomId, payload, from, ts }
     8→ *
     9→ * 메시지 타입:
    10→ *   join        - 룸 입장
    11→ *   leave       - 룸 퇴장
    12→ *   graph_update - 그래프 변경 (브로드캐스트)
    13→ *   node_add    - 노드 추가
    14→ *   node_remove - 노드 삭제
    15→ *   node_move   - 노드 위치 이동
    16→ *   edge_add    - 엣지 추가
    17→ *   edge_remove - 엣지 삭제
    18→ *   cursor_move - 커서 위치 (실시간)
    19→ *   ping / pong - 연결 유지
    20→ */
    21→
    22→'use strict';
    23→
    24→const http = require('http');
    25→
    26→// ─── 상수 ──────────────────────────────────────────────────────
    27→
    28→const WS_PORT         = process.env.FREEWIRE_WS_PORT || 4011;
    29→const MAX_ROOMS       = 50;
    30→const MAX_CLIENTS_PER_ROOM = 20;
    31→const MAX_MSG_BYTES   = 512_000;   // 512KB
    32→const PING_INTERVAL   = 30_000;   // 30초
    33→
    34→// WebSocket 오피코드
    35→const OP_CONT  = 0x0;
    36→const OP_TEXT  = 0x1;
    37→const OP_CLOSE = 0x8;
    38→const OP_PING  = 0x9;
    39→const OP_PONG  = 0xA;
    40→
    41→// ─── 상태 ──────────────────────────────────────────────────────
    42→
    43→/** @type {Map<string, { clients: Map<string, WsClient>, graph: object, createdAt: number }>} */
    44→const rooms = new Map();
    45→
    46→/** @type {Map<object, WsClient>} */
    47→const clients = new Map();
    48→
    49→// ─── WsClient ────────────────────────────────────────────────
    50→
    51→class WsClient {
    52→  constructor(socket, id) {
    53→    this.socket  = socket;
    54→    this.id      = id;
    55→    this.roomId  = null;
    56→    this.alive   = true;
    57→    this.buf     = Buffer.alloc(0);
    58→  }
    59→
    60→  send(obj) {
    61→    try {
    62→      const json  = JSON.stringify(obj);
    63→      const frame = encodeFrame(json);
    64→      this.socket.write(frame);
    65→    } catch { /* 소켓 닫힘 */ }
    66→  }
    67→
    68→  close(code = 1000, reason = '') {
    69→    try {
    70→      const buf = Buffer.alloc(2 + reason.length);
    71→      buf.writeUInt16BE(code, 0);
    72→      buf.write(reason, 2);
    73→      this.socket.write(encodeFrame(buf, OP_CLOSE));
    74→      this.socket.end();
    75→    } catch { this.socket.destroy(); }
    76→  }
    77→}
    78→
    79→// ─── WebSocket 핸드쉐이크 ────────────────────────────────────
    80→
    81→const GUID = '258EAFA5-E914-47DA-95CA-C5AB0DC85B11';
    82→
    83→function doHandshake(req, socket) {
    84→  const key = req.headers['sec-websocket-key'];
    85→  if (!key) { socket.destroy(); return false; }
    86→
    87→  const crypto = require('crypto');
    88→  const accept = crypto.createHash('sha1')
    89→    .update(key + GUID)
    90→    .digest('base64');
    91→
    92→  socket.write(
    93→    'HTTP/1.1 101 Switching Protocols\r\n' +
    94→    'Upgrade: websocket\r\n' +
    95→    'Connection: Upgrade\r\n' +
    96→    `Sec-WebSocket-Accept: ${accept}\r\n` +
    97→    '\r\n'
    98→  );
    99→  return true;
   100→}
   101→
   102→// ─── 프레임 인코딩 ────────────────────────────────────────────
   103→
   104→function encodeFrame(data, opcode = OP_TEXT) {
   105→  const payload = typeof data === 'string' ? Buffer.from(data, 'utf8') : data;
   106→  const len     = payload.length;
   107→
   108→  let header;
   109→  if (len < 126) {
   110→    header = Buffer.alloc(2);
   111→    header[0] = 0x80 | opcode;
   112→    header[1] = len;
   113→  } else if (len < 65536) {
   114→    header = Buffer.alloc(4);
   115→    header[0] = 0x80 | opcode;
   116→    header[1] = 126;
   117→    header.writeUInt16BE(len, 2);
   118→  } else {
   119→    header = Buffer.alloc(10);
   120→    header[0] = 0x80 | opcode;
   121→    header[1] = 127;
   122→    header.writeBigUInt64BE(BigInt(len), 2);
   123→  }
   124→  return Buffer.concat([header, payload]);
   125→}
   126→
   127→// ─── 프레임 디코딩 ────────────────────────────────────────────
   128→
   129→function decodeFrame(buf) {
   130→  if (buf.length < 2) return null;
   131→
   132→  const fin    = (buf[0] & 0x80) !== 0;
   133→  const opcode = buf[0] & 0x0F;
   134→  const masked = (buf[1] & 0x80) !== 0;
   135→  let   payLen = buf[1] & 0x7F;
   136→  let   offset = 2;
   137→
   138→  if (payLen === 126) {
   139→    if (buf.length < 4) return null;
   140→    payLen = buf.readUInt16BE(2);
   141→    offset = 4;
   142→  } else if (payLen === 127) {
   143→    if (buf.length < 10) return null;
   144→    payLen = Number(buf.readBigUInt64BE(2));
   145→    offset = 10;
   146→  }
   147→
   148→  if (masked) offset += 4;
   149→  if (buf.length < offset + payLen) return null;
   150→
   151→  const maskKey = masked ? buf.slice(offset - 4, offset) : null;
   152→  const payload = Buffer.from(buf.slice(offset, offset + payLen));
   153→
   154→  if (masked && maskKey) {
   155→    for (let i = 0; i < payload.length; i++) {
   156→      payload[i] ^= maskKey[i % 4];
   157→    }
   158→  }
   159→
   160→  return { fin, opcode, payload, consumed: offset + payLen };
   161→}
   162→
   163→// ─── 룸 관리 ──────────────────────────────────────────────────
   164→
   165→function getOrCreateRoom(roomId) {
   166→  if (!rooms.has(roomId)) {
   167→    if (rooms.size >= MAX_ROOMS) {
   168→      // 가장 오래된 빈 룸 제거
   169→      for (const [id, room] of rooms) {
   170→        if (room.clients.size === 0) { rooms.delete(id); break; }
   171→      }
   172→    }
   173→    rooms.set(roomId, {
   174→      clients:   new Map(),
   175→      graph:     { nodes: [], edges: [], id: roomId },
   176→      createdAt: Date.now(),
   177→    });
   178→  }
   179→  return rooms.get(roomId);
   180→}
   181→
   182→function broadcast(roomId, msg, excludeId = null) {
   183→  const room = rooms.get(roomId);
   184→  if (!room) return;
   185→  for (const [id, client] of room.clients) {
   186→    if (id !== excludeId) client.send(msg);
   187→  }
   188→}
   189→
   190→function getRoomInfo(roomId) {
   191→  const room = rooms.get(roomId);
   192→  if (!room) return null;
   193→  return {
   194→    roomId,
   195→    clientCount: room.clients.size,
   196→    clients:     [...room.clients.keys()],
   197→    graph:       room.graph,
   198→  };
   199→}
   200→
   201→// ─── 메시지 핸들러 ────────────────────────────────────────────
   202→
   203→function handleMessage(client, raw) {
   204→  let msg;
   205→  try { msg = JSON.parse(raw); }
   206→  catch { return client.send({ type: 'error', error: '잘못된 JSON' }); }
   207→
   208→  const { type, roomId, payload } = msg;
   209→
   210→  switch (type) {
   211→    case 'join': {
   212→      if (!roomId) return client.send({ type: 'error', error: 'roomId 필수' });
   213→      const room = getOrCreateRoom(roomId);
   214→      if (room.clients.size >= MAX_CLIENTS_PER_ROOM) {
   215→        return client.send({ type: 'error', error: '룸 최대 인원 초과' });
   216→      }
   217→      // 이전 룸에서 퇴장
   218→      if (client.roomId) leaveRoom(client);
   219→
   220→      client.roomId = roomId;
   221→      room.clients.set(client.id, client);
   222→
   223→      // 입장 확인 + 현재 그래프 상태 전송
   224→      client.send({ type: 'joined', roomId, graph: room.graph, clientId: client.id });
   225→      // 다른 클라이언트에게 알림
   226→      broadcast(roomId, { type: 'peer_joined', roomId, clientId: client.id, clientCount: room.clients.size }, client.id);
   227→      break;
   228→    }
   229→
   230→    case 'leave':
   231→      leaveRoom(client);
   232→      break;
   233→
   234→    case 'graph_update': {
   235→      const room = rooms.get(client.roomId);
   236→      if (!room) return client.send({ type: 'error', error: '룸 없음' });
   237→      if (payload?.graph) room.graph = payload.graph;
   238→      broadcast(client.roomId, { type: 'graph_update', roomId: client.roomId, payload, from: client.id, ts: Date.now() }, client.id);
   239→      break;
   240→    }
   241→
   242→    case 'node_add':
   243→    case 'node_remove':
   244→    case 'node_move':
   245→    case 'edge_add':
   246→    case 'edge_remove': {
   247→      const room = rooms.get(client.roomId);
   248→      if (!room) return client.send({ type: 'error', error: '룸 없음' });
   249→      // 그래프 상태 업데이트
   250→      _applyOp(room.graph, type, payload);
   251→      broadcast(client.roomId, { type, roomId: client.roomId, payload, from: client.id, ts: Date.now() }, client.id);
   252→      break;
   253→    }
   254→
   255→    case 'cursor_move':
   256→      // 커서 이동은 저장 없이 브로드캐스트만
   257→      broadcast(client.roomId, { type: 'cursor_move', roomId: client.roomId, payload, from: client.id, ts: Date.now() }, client.id);
   258→      break;
   259→
   260→    case 'ping':
   261→      client.send({ type: 'pong', ts: Date.now() });
   262→      break;
   263→
   264→    case 'room_info':
   265→      client.send({ type: 'room_info', data: getRoomInfo(client.roomId) });
   266→      break;
   267→
   268→    default:
   269→      client.send({ type: 'error', error: `알 수 없는 타입: ${type}` });
   270→  }
   271→}
   272→
   273→function _applyOp(graph, type, payload) {
   274→  if (!payload) return;
   275→  switch (type) {
   276→    case 'node_add':
   277→      if (payload.node) graph.nodes.push(payload.node);
   278→      break;
   279→    case 'node_remove':
   280→      if (payload.nodeId) {
   281→        graph.nodes = graph.nodes.filter(n => n.id !== payload.nodeId);
   282→        graph.edges = graph.edges.filter(e => e.fn !== payload.nodeId && e.tn !== payload.nodeId);
   283→      }
   284→      break;
   285→    case 'node_move':
   286→      if (payload.nodeId) {
   287→        const n = graph.nodes.find(n => n.id === payload.nodeId);
   288→        if (n && payload.position) n.position = payload.position;
   289→      }
   290→      break;
   291→    case 'edge_add':
   292→      if (payload.edge) graph.edges.push(payload.edge);
   293→      break;
   294→    case 'edge_remove':
   295→      if (payload.edgeId) graph.edges = graph.edges.filter((_, i) => i !== payload.edgeId);
   296→      break;
   297→  }
   298→}
   299→
   300→function leaveRoom(client) {
   301→  if (!client.roomId) return;
   302→  const room = rooms.get(client.roomId);
   303→  if (room) {
   304→    room.clients.delete(client.id);
   305→    broadcast(client.roomId, { type: 'peer_left', roomId: client.roomId, clientId: client.id, clientCount: room.clients.size });
   306→    // 빈 룸 정리 (10분 후)
   307→    if (room.clients.size === 0) {
   308→      setTimeout(() => {
   309→        const r = rooms.get(client.roomId);
   310→        if (r && r.clients.size === 0) rooms.delete(client.roomId);
   311→      }, 600_000);
   312→    }
   313→  }
   314→  client.roomId = null;
   315→}
   316→
   317→// ─── 서버 생성 ────────────────────────────────────────────────
   318→
   319→let _clientIdCtr = 0;
   320→
   321→function createWsServer() {
   322→  const server = http.createServer((req, res) => {
   323→    // HTTP REST 엔드포인트
   324→    if (req.url === '/ws/health') {
   325→      res.writeHead(200, { 'Content-Type': 'application/json' });
   326→      res.end(JSON.stringify({ status: 'ok', rooms: rooms.size, clients: clients.size }));
   327→      return;
   328→    }
   329→    if (req.url === '/ws/rooms') {
   330→      const list = [...rooms.entries()].map(([id, r]) => ({
   331→        roomId: id, clientCount: r.clients.size, createdAt: r.createdAt,
   332→      }));
   333→      res.writeHead(200, { 'Content-Type': 'application/json' });
   334→      res.end(JSON.stringify({ rooms: list }));
   335→      return;
   336→    }
   337→    res.writeHead(426, { 'Content-Type': 'text/plain' });
   338→    res.end('WebSocket Upgrade Required');
   339→  });
   340→
   341→  server.on('upgrade', (req, socket, head) => {
   342→    if (!doHandshake(req, socket)) return;
   343→
   344→    const clientId = `c${++_clientIdCtr}-${Date.now()}`;
   345→    const client   = new WsClient(socket, clientId);
   346→    clients.set(socket, client);
   347→
   348→    socket.on('data', (chunk) => {
   349→      client.buf = Buffer.concat([client.buf, chunk]);
   350→      if (client.buf.length > MAX_MSG_BYTES) {
   351→        client.close(1009, '메시지 너무 큼');
   352→        return;
   353→      }
   354→
   355→      while (client.buf.length > 0) {
   356→        const frame = decodeFrame(client.buf);
   357→        if (!frame) break;
   358→        client.buf = client.buf.slice(frame.consumed);
   359→
   360→        switch (frame.opcode) {
   361→          case OP_TEXT:
   362→            client.alive = true;
   363→            handleMessage(client, frame.payload.toString('utf8'));
   364→            break;
   365→          case OP_PING:
   366→            socket.write(encodeFrame(frame.payload, OP_PONG));
   367→            break;
   368→          case OP_CLOSE:
   369→            leaveRoom(client);
   370→            clients.delete(socket);
   371→            socket.end();
   372→            break;
   373→        }
   374→      }
   375→    });
   376→
   377→    socket.on('close', () => {
   378→      leaveRoom(client);
   379→      clients.delete(socket);
   380→    });
   381→
   382→    socket.on('error', () => {
   383→      leaveRoom(client);
   384→      clients.delete(socket);
   385→    });
   386→
   387→    // 연결 확인 메시지
   388→    client.send({ type: 'connected', clientId, ts: Date.now() });
   389→  });
   390→
   391→  // Ping/Pong 유지
   392→  const pingTimer = setInterval(() => {
   393→    for (const [sock, client] of clients) {
   394→      if (!client.alive) { sock.destroy(); continue; }
   395→      client.alive = false;
   396→      try { sock.write(encodeFrame(Buffer.alloc(0), OP_PING)); }
   397→      catch { sock.destroy(); }
   398→    }
   399→  }, PING_INTERVAL);
   400→
   401→  server.on('close', () => clearInterval(pingTimer));
   402→
   403→  return server;
   404→}
   405→
   406→// ─── 공개 API ────────────────────────────────────────────────
   407→
   408→const wsServer = createWsServer();
   409→
   410→if (require.main === module) {
   411→  wsServer.listen(WS_PORT, () => {
   412→    console.log(`\n🔌 FreeWire WebSocket 서버 시작`);
   413→    console.log(`   ws://localhost:${WS_PORT}`);
   414→    console.log(`   GET http://localhost:${WS_PORT}/ws/health`);
   415→    console.log(`   GET http://localhost:${WS_PORT}/ws/rooms\n`);
   416→  });
   417→}
   418→
   419→module.exports = { wsServer, rooms, clients, broadcast, getRoomInfo };
   420→

