     1→/**
     2→ * FreeWire Phase 7 — Intent Evaluator
     3→ *
     4→ * "버튼이 렌더되나?" 가 아니라
     5→ * "인증이 시작될 수 있는 상태인가?" 를 판단한다.
     6→ *
     7→ * 세 가지를 검사한다:
     8→ *   1. Structural Check  — 필요한 노드/와이어가 존재하는가?
     9→ *   2. Contract Check    — 각 노드의 requires가 충족되는가?
    10→ *   3. Goal Check        — 목표 Facts가 그래프에서 생산 가능한가?
    11→ */
    12→
    13→'use strict';
    14→
    15→const { NODE_INTENT_DEFAULTS, parseGoalToFacts, wireFrom, wireTo } = require('./intent-spec');
    16→
    17→// ─── 위반 구조 ─────────────────────────────────────────────────
    18→
    19→class ContractViolation {
    20→  constructor({ nodeId, nodeLabel, type, fact, message, severity, repairHint }) {
    21→    this.nodeId    = nodeId;
    22→    this.nodeLabel = nodeLabel;
    23→    this.type      = type;       // 'requires' | 'ensures' | 'goal' | 'structural' | 'warning'
    24→    this.fact      = fact;       // 위반된 fact
    25→    this.message   = message;    // 사람이 읽을 수 있는 설명
    26→    this.severity  = severity;   // 'error' | 'warning'
    27→    this.repairHint= repairHint; // 수정 방향 힌트
    28→  }
    29→
    30→  toString() {
    31→    const sev = this.severity ?? 'unknown';
    32→    return `[${sev.toUpperCase()}] ${this.nodeLabel}: ${this.message}`;
    33→  }
    34→}
    35→
    36→// ─── Intent Evaluator ──────────────────────────────────────────
    37→
    38→class IntentEvaluator {
    39→  /**
    40→   * @param {Map}    nodes  - editor.nodes (NodeView Map)
    41→   * @param {Map}    wires  - editor.wires (wire Map)
    42→   * @param {string} goal   - 사용자 원래 의도 ("로그인 폼 만들어줘")
    43→   */
    44→  evaluate(nodes, wires, goal = '') {
    45→    if (!nodes || typeof nodes.values !== 'function') nodes = new Map();
    46→    if (!wires || typeof wires.values !== 'function') wires = new Map();
    47→    const nodesArr = this._extractDefs(nodes);
    48→    const wiresArr = [...wires.values()];
    49→
    50→    const violations = [];
    51→    const satisfiedFacts = new Set();
    52→
    53→    // 1) 구조 검사: 빈 그래프
    54→    if (nodesArr.length === 0) {
    55→      violations.push(new ContractViolation({
    56→        nodeId: null, nodeLabel: '그래프',
    57→        type: 'structural', fact: 'graph.nonempty',
    58→        message: '노드가 없습니다. UI를 만들려면 노드를 추가하세요.',
    59→        severity: 'error', repairHint: 'add_node',
    60→      }));
    61→      return this._buildReport(violations, satisfiedFacts, goal, nodesArr, wiresArr);
    62→    }
    63→
    64→    // 2) 각 노드의 Contract 검사
    65→    for (const node of nodesArr) {
    66→      const contract = node.contract ?? this._getDefaultContract(node.subtype);
    67→      const producedByConnected = this._factsProducedByInputs(node, nodesArr, wiresArr);
    68→
    69→      // requires 검사
    70→      for (const req of (contract.requires ?? [])) {
    71→        if (!producedByConnected.has(req) && !satisfiedFacts.has(req)) {
    72→          violations.push(new ContractViolation({
    73→            nodeId: node.id, nodeLabel: node.label ?? node.subtype,
    74→            type: 'requires', fact: req,
    75→            message: `"${req}" 조건이 필요하지만 연결된 노드가 제공하지 않습니다.`,
    76→            severity: 'error',
    77→            repairHint: `connect_${req.split('.')[0]}`,
    78→          }));
    79→        }
    80→      }
    81→
    82→      // warns 검사 (권장)
    83→      for (const warn of (contract.warns ?? [])) {
    84→        if (!producedByConnected.has(warn)) {
    85→          violations.push(new ContractViolation({
    86→            nodeId: node.id, nodeLabel: node.label ?? node.subtype,
    87→            type: 'warning', fact: warn,
    88→            message: `"${warn}" 조건이 충족되면 더 완전한 UI가 됩니다.`,
    89→            severity: 'warning',
    90→            repairHint: `enhance_${warn.split('.')[0]}`,
    91→          }));
    92→        }
    93→      }
    94→
    95→      // 이 노드가 produces하는 facts 수집
    96→      for (const p of (contract.produces ?? [])) satisfiedFacts.add(p);
    97→      for (const e of (contract.ensures ?? []))  satisfiedFacts.add(e);
    98→    }
    99→
   100→    // 3) 특수 구조 검사
   101→    this._checkButtonHandlerConnections(nodesArr, wiresArr, violations);
   102→    this._checkStateBindings(nodesArr, wiresArr, violations, satisfiedFacts);
   103→    this._checkOrphanNodes(nodesArr, wiresArr, violations);
   104→
   105→    // 4) Goal Facts 검사
   106→    if (goal) {
   107→      const goalFacts = parseGoalToFacts(goal);
   108→      for (const gf of goalFacts) {
   109→        if (!satisfiedFacts.has(gf)) {
   110→          violations.push(new ContractViolation({
   111→            nodeId: null, nodeLabel: '목표',
   112→            type: 'goal', fact: gf,
   113→            message: `목표 달성에 필요한 "${gf}"가 현재 그래프에서 생산되지 않습니다.`,
   114→            severity: 'error',
   115→            repairHint: `goal_${gf.replace(/\./g, '_')}`,
   116→          }));
   117→        }
   118→      }
   119→    }
   120→
   121→    return this._buildReport(violations, satisfiedFacts, goal, nodesArr, wiresArr);
   122→  }
   123→
   124→  // ─── 특수 구조 검사들 ──────────────────────────────────────
   125→
   126→  _checkButtonHandlerConnections(nodesArr, wiresArr, violations) {
   127→    const buttons  = nodesArr.filter(n => n.subtype === 'button');
   128→    const handlers = nodesArr.filter(n => n.subtype === 'handler');
   129→
   130→    for (const btn of buttons) {
   131→      // 버튼의 onClick 포트(인덱스 1)에 핸들러가 연결됐는지 확인
   132→      const connected = wiresArr.some(w =>
   133→        wireTo(w) === btn.id && (w.tp ?? w.toPort ?? w.to?.portId) === 1
   134→      );
   135→      if (!connected && handlers.length > 0) {
   136→        violations.push(new ContractViolation({
   137→          nodeId: btn.id, nodeLabel: btn.label ?? '버튼',
   138→          type: 'structural', fact: 'ui.button.connected',
   139→          message: `버튼 "${btn.props?.label ?? btn.id}"에 클릭 핸들러가 연결되지 않았습니다. 클릭해도 아무 일도 일어나지 않습니다.`,
   140→          severity: 'error',
   141→          repairHint: 'wire_handler_to_button',
   142→        }));
   143→      }
   144→    }
   145→
   146→    // 핸들러가 아예 없는데 버튼은 있는 경우
   147→    if (buttons.length > 0 && handlers.length === 0) {
   148→      violations.push(new ContractViolation({
   149→        nodeId: null, nodeLabel: '그래프',
   150→        type: 'structural', fact: 'action.handler.present',
   151→        message: `버튼이 ${buttons.length}개 있지만 이벤트 핸들러가 없습니다. 버튼 클릭이 동작하지 않습니다.`,
   152→        severity: 'error',
   153→        repairHint: 'add_handler_node',
   154→      }));
   155→    }
   156→  }
   157→
   158→  _checkStateBindings(nodesArr, wiresArr, violations, satisfiedFacts) {
   159→    const stateNodes = nodesArr.filter(n => n.subtype === 'state');
   160→    const textNodes  = nodesArr.filter(n => n.subtype === 'text');
   161→
   162→    for (const st of stateNodes) {
   163→      // state가 text/컴포넌트에 연결됐는지
   164→      const hasOutput = wiresArr.some(w => wireFrom(w) === st.id);
   165→      if (!hasOutput && textNodes.length > 0) {
   166→        violations.push(new ContractViolation({
   167→          nodeId: st.id, nodeLabel: st.label ?? '상태',
   168→          type: 'structural', fact: 'state.bound',
   169→          message: `상태 "${st.props?.name ?? st.id}"가 UI에 바인딩되지 않았습니다. 상태가 변해도 화면이 갱신되지 않습니다.`,
   170→          severity: 'warning',
   171→          repairHint: 'wire_state_to_display',
   172→        }));
   173→      } else if (hasOutput) {
   174→        satisfiedFacts.add('state.bound');
   175→      }
   176→    }
   177→  }
   178→
   179→  _checkOrphanNodes(nodesArr, wiresArr, violations) {
   180→    if (nodesArr.length < 3) return; // 소규모 그래프는 고아 체크 생략
   181→
   182→    for (const node of nodesArr) {
   183→      if (node.type !== 'component') continue;
   184→      const hasAnyWire = wiresArr.some(w =>
   185→        wireFrom(w) === node.id || wireTo(w) === node.id
   186→      );
   187→      if (!hasAnyWire) {
   188→        violations.push(new ContractViolation({
   189→          nodeId: node.id, nodeLabel: node.label ?? node.subtype,
   190→          type: 'structural', fact: 'node.connected',
   191→          message: `노드 "${node.label ?? node.id}"가 다른 노드와 연결되지 않았습니다. 고립된 상태입니다.`,
   192→          severity: 'warning',
   193→          repairHint: 'connect_orphan',
   194→        }));
   195→      }
   196→    }
   197→  }
   198→
   199→  // ─── 헬퍼 ────────────────────────────────────────────────────
   200→
   201→  _extractDefs(nodes) {
   202→    return [...nodes.values()].map(v => v.def ?? v);
   203→  }
   204→
   205→  _getDefaultContract(subtype) {
   206→    return NODE_INTENT_DEFAULTS[subtype]?.contract ?? { requires: [], ensures: [], produces: [], warns: [] };
   207→  }
   208→
   209→  /**
   210→   * 이 노드의 입력 포트에 연결된 노드들이 produces하는 facts
   211→   */
   212→  _factsProducedByInputs(node, nodesArr, wiresArr) {
   213→    const produced = new Set();
   214→    const inputWires = wiresArr.filter(w => wireTo(w) === node.id);
   215→
   216→    for (const wire of inputWires) {
   217→      const sourceNode = nodesArr.find(n => n.id === wireFrom(wire));
   218→      if (!sourceNode) continue;
   219→      const contract = sourceNode.contract ?? this._getDefaultContract(sourceNode.subtype);
   220→      for (const p of (contract.produces ?? [])) produced.add(p);
   221→      for (const e of (contract.ensures  ?? [])) produced.add(e);
   222→    }
   223→
   224→    return produced;
   225→  }
   226→
   227→  _buildReport(violations, satisfiedFacts, goal, nodesArr, wiresArr) {
   228→    const errors   = violations.filter(v => v.severity === 'error');
   229→    const warnings = violations.filter(v => v.severity === 'warning');
   230→
   231→    const totalFacts     = goal ? parseGoalToFacts(goal) : [];
   232→    const satisfiedGoals = totalFacts.filter(f => satisfiedFacts.has(f));
   233→    const score = totalFacts.length > 0
   234→      ? Math.round((satisfiedGoals.length / totalFacts.length) * 100)
   235→      : (errors.length === 0 ? 100 : 0);
   236→
   237→    return {
   238→      score,                    // 0-100 — 의도 충족 점수
   239→      passed: errors.length === 0,
   240→      errors,
   241→      warnings,
   242→      violations,
   243→      satisfiedFacts: [...satisfiedFacts],
   244→      missingFacts: totalFacts.filter(f => !satisfiedFacts.has(f)),
   245→      summary: this._buildSummary(score, errors, warnings, nodesArr, wiresArr),
   246→    };
   247→  }
   248→
   249→  _buildSummary(score, errors, warnings, nodesArr, wiresArr) {
   250→    if (errors.length === 0 && warnings.length === 0) {
   251→      return `✅ 의도 100% 충족 — 모든 계약이 만족됩니다`;
   252→    }
   253→    const parts = [];
   254→    if (score < 100) parts.push(`의도 충족률: ${score}%`);
   255→    if (errors.length)   parts.push(`오류 ${errors.length}개`);
   256→    if (warnings.length) parts.push(`경고 ${warnings.length}개`);
   257→    parts.push(`노드 ${nodesArr.length}개 / 와이어 ${wiresArr.length}개`);
   258→    return parts.join(' | ');
   259→  }
   260→}
   261→
   262→module.exports = { IntentEvaluator, ContractViolation };
   263→

