     1→/**
     2→ * FreeWire - Graph → FreeLang Light 컴파일러
     3→ * 노드 그래프 JSON → 완성된 .free 파일 문자열 생성
     4→ */
     5→
     6→const { Graph }              = require('../core/graph');
     7→const { toFreelangMarkup }   = require('../core/nodes/component');
     8→const { toFreelangCode: dataToCode }  = require('../core/nodes/data');
     9→const { toFreelangCode: logicToCode } = require('../core/nodes/logic');
    10→const { getBridge }          = require('../core/plugin-bridge');
    11→
    12→class GraphCompiler {
    13→  constructor() {
    14→    this.errors   = [];
    15→    this.warnings = [];
    16→  }
    17→
    18→  /**
    19→   * Graph 인스턴스 또는 JSON → .free 파일 문자열
    20→   * @param {Graph|object} input
    21→   * @returns {{ code: string, errors: string[], warnings: string[] }}
    22→   */
    23→  compile(input) {
    24→    this.errors   = [];
    25→    this.warnings = [];
    26→
    27→    const graph = input instanceof Graph ? input : Graph.fromJSON(input);
    28→    const sorted = graph.topologicalSort();
    29→
    30→    const bridge         = getBridge();
    31→    const propsNodes     = sorted.filter(n => n.type === 'data' && n.dataType === 'props');
    32→    const stateNodes     = sorted.filter(n => n.type === 'data' && n.dataType === 'state');
    33→    const stdlibNodes    = sorted.filter(n => bridge.isStdlibNode(n));
    34→    const constNodes     = sorted.filter(n => n.type === 'data' && !['props','state'].includes(n.dataType) && !bridge.isStdlibNode(n));
    35→    const logicNodes     = sorted.filter(n => n.type === 'logic');
    36→    const componentNodes = sorted.filter(n => n.type === 'component');
    37→
    38→    if (componentNodes.length === 0) {
    39→      this.warnings.push('component 노드가 없습니다. markup 블록이 비어 있습니다.');
    40→    }
    41→
    42→    // 컴포넌트 이름: 그래프 id 또는 첫 component 이름
    43→    const compName = this._resolveComponentName(graph, componentNodes);
    44→
    45→    const sections = [];
    46→
    47→    // 1) component 헤더
    48→    sections.push(`component ${compName} {`);
    49→
    50→    // 2) props 블록
    51→    const propsBlock = this._buildPropsBlock(propsNodes);
    52→    if (propsBlock) sections.push(propsBlock);
    53→
    54→    // 3) style 블록 (component props에서 수집)
    55→    const styleBlock = this._buildStyleBlock(componentNodes);
    56→    if (styleBlock) sections.push(styleBlock);
    57→
    58→    // 4) script 블록 (state + const + stdlib + logic)
    59→    const scriptBlock = this._buildScriptBlock(stateNodes, constNodes, logicNodes, graph, stdlibNodes);
    60→    if (scriptBlock) sections.push(scriptBlock);
    61→
    62→    // 5) markup 블록
    63→    const markupBlock = this._buildMarkupBlock(componentNodes, graph);
    64→    sections.push(markupBlock);
    65→
    66→    sections.push('}');
    67→
    68→    return {
    69→      code:     sections.join('\n\n'),
    70→      errors:   this.errors,
    71→      warnings: this.warnings,
    72→    };
    73→  }
    74→
    75→  // ─── 내부 빌더 ──────────────────────────────────────────────
    76→
    77→  _resolveComponentName(graph, componentNodes) {
    78→    if (componentNodes.length > 0 && componentNodes[0].props?.name) {
    79→      return componentNodes[0].props.name;
    80→    }
    81→    return graph.id.replace(/[^a-zA-Z0-9]/g, '_') || 'MyComponent';
    82→  }
    83→
    84→  _buildPropsBlock(propsNodes) {
    85→    if (propsNodes.length === 0) return null;
    86→    const lines = propsNodes.map(n => {
    87→      if (!n.props) {
    88→        this.warnings.push(`props 노드 [${n.id}]에 props 객체 없음 - 건너뜀`);
    89→        return null;
    90→      }
    91→      const { name, value, required } = n.props;
    92→      if (!name) {
    93→        this.warnings.push(`props 노드 [${n.id}]에 name 없음 - 건너뜀`);
    94→        return null;
    95→      }
    96→      const req = required ? '' : `= ${JSON.stringify(value ?? null)}`;
    97→      return `  ${name}: ${n.dataType ?? 'any'} ${req}`.trimEnd() + ';';
    98→    }).filter(Boolean);
    99→    return `  props {\n${lines.join('\n')}\n  }`;
   100→  }
   101→
   102→  _buildStyleBlock(componentNodes) {
   103→    const styleLines = [];
   104→    componentNodes.forEach(n => {
   105→      const p = n.props;
   106→      const selector = `.${n.componentType}`;
   107→      const rules = [];
   108→
   109→      if (p.color)        rules.push(`color: ${p.color}`);
   110→      if (p.background)   rules.push(`background: ${p.background}`);
   111→      if (p.padding)      rules.push(`padding: ${p.padding}`);
   112→      if (p.gap)          rules.push(`gap: ${p.gap}`);
   113→      if (p.fontSize)     rules.push(`font-size: ${p.fontSize}`);
   114→      if (p.borderRadius) rules.push(`border-radius: ${p.borderRadius}`);
   115→      if (p.direction && n.componentType === 'container') {
   116→        rules.push(`display: flex`);
   117→        rules.push(`flex-direction: ${p.direction}`);
   118→      }
   119→
   120→      if (rules.length > 0) {
   121→        styleLines.push(`  ${selector} {`);
   122→        rules.forEach(r => styleLines.push(`    ${r};`));
   123→        styleLines.push(`  }`);
   124→      }
   125→    });
   126→
   127→    if (styleLines.length === 0) return null;
   128→    return `  style {\n${styleLines.join('\n')}\n  }`;
   129→  }
   130→
   131→  _buildScriptBlock(stateNodes, constNodes, logicNodes, graph, stdlibNodes = []) {
   132→    const lines = [];
   133→
   134→    // 상수
   135→    constNodes.forEach(n => {
   136→      lines.push(`  let ${n.props.name} = ${JSON.stringify(n.props.value)};`);
   137→    });
   138→
   139→    // 상태
   140→    stateNodes.forEach(n => {
   141→      lines.push(`  let ${n.props.name} = ${JSON.stringify(n.props.value)};`);
   142→      lines.push(`  function set_${n.props.name}(v) { ${n.props.name} = v; }`);
   143→    });
   144→
   145→    // stdlib 노드 — PluginBridge가 코드 생성
   146→    if (stdlibNodes.length > 0) {
   147→      const bridge = getBridge();
   148→      lines.push('  // ── stdlib 함수 ──');
   149→      stdlibNodes.forEach(n => {
   150→        const code = bridge.codeGenNode(n);
   151→        // 들여쓰기 맞추기
   152→        code.split('\n').forEach(line => lines.push(`  ${line}`));
   153→      });
   154→    }
   155→
   156→    // 로직 노드 (연결 정보 포함)
   157→    logicNodes.forEach(n => {
   158→      const code = this._logicNodeToScript(n, graph);
   159→      if (code) lines.push(code);
   160→    });
   161→
   162→    if (lines.length === 0) return null;
   163→    return `  script {\n${lines.join('\n')}\n  }`;
   164→  }
   165→
   166→  _logicNodeToScript(node, graph) {
   167→    const { logicType, props } = node;
   168→
   169→    // 입력 연결에서 실제 값/노드 id 추론
   170→    const inEdges = graph.incomingEdges(node.id);
   171→    const getConnected = (portId) => {
   172→      const e = inEdges.find(e => e.to.portId === portId);
   173→      return e ? e.from.nodeId : null;
   174→    };
   175→
   176→    switch (logicType) {
   177→      case 'if': {
   178→        const cond = props.condition || getConnected('condition') || 'true';
   179→        return [
   180→          `  if (${cond}) {`,
   181→          `    // then: ${getConnected('then') || '연결 없음'}`,
   182→          `  } else {`,
   183→          `    // else: ${getConnected('else') || '연결 없음'}`,
   184→          `  }`,
   185→        ].join('\n');
   186→      }
   187→      case 'function':
   188→        return [
   189→          `  function ${props.name}(${(props.params || []).join(', ')}) {`,
   190→          `    ${props.body || 'return null;'}`,
   191→          `  }`,
   192→        ].join('\n');
   193→      case 'map':
   194→        return `  let ${node.id}_result = (${getConnected('array') || '[]'}).map(function(${props.itemName}) { return ${props.expression}; });`;
   195→      case 'filter':
   196→        return `  let ${node.id}_result = (${getConnected('array') || '[]'}).filter(function(${props.itemName}) { return ${props.condition}; });`;
   197→      case 'reduce':
   198→        return `  let ${node.id}_result = (${getConnected('array') || '[]'}).reduce(function(${props.accumName}, ${props.itemName}) { return ${props.expression}; }, ${props.initial});`;
   199→      case 'loop':
   200→        return null; // markup 블록에서 처리
   201→      default:
   202→        this.warnings.push(`알 수 없는 logicType: ${logicType}`);
   203→        return null;
   204→    }
   205→  }
   206→
   207→  _buildMarkupBlock(componentNodes, graph) {
   208→    if (componentNodes.length === 0) {
   209→      return `  markup {\n    <!-- 컴포넌트 없음 -->\n  }`;
   210→    }
   211→
   212→    // 루트 컴포넌트: 다른 노드의 출력을 받지 않는 component
   213→    const childIds = new Set(
   214→      graph.edges
   215→        .filter(e => e.to.portId === 'children' || e.from.portType === 'component')
   216→        .map(e => e.to.nodeId)
   217→    );
   218→    const roots = componentNodes.filter(n => !childIds.has(n.id));
   219→    const renderTargets = roots.length > 0 ? roots : [componentNodes[0]];
   220→
   221→    const lines = ['  markup {'];
   222→    renderTargets.forEach(n => {
   223→      // subtype → componentType 정규화 (API 입력 호환)
   224→      if (!n.componentType && n.subtype) n = { ...n, componentType: n.subtype };
   225→      const markup = toFreelangMarkup(n);
   226→      // 들여쓰기 맞추기
   227→      markup.split('\n').forEach(line => {
   228→        lines.push('  ' + line);
   229→      });
   230→    });
   231→    lines.push('  }');
   232→    return lines.join('\n');
   233→  }
   234→}
   235→
   236→module.exports = { GraphCompiler };
   237→

