     1→/**
     2→ * FreeWire — Plugin Bridge
     3→ *
     4→ * freelang-ecosystem의 플러그인 시스템과 FreeWire를 연결합니다.
     5→ *
     6→ * 기능:
     7→ *   1. PluginLoader로 freewire-stdlib 플러그인 로드
     8→ *   2. 노드 팔레트에 stdlib 카테고리 추가
     9→ *   3. GraphCompiler가 stdlib 노드 코드 생성에 사용할 codeGenNode() 제공
    10→ *   4. GET /api/nodes 응답에 stdlib 카테고리 포함
    11→ */
    12→'use strict';
    13→
    14→const path = require('path');
    15→
    16→// freelang-ecosystem 경로 (FreeWire와 같은 레벨에 위치)
    17→const ECOSYSTEM_PATH = path.resolve(__dirname, '../../../../freelang-ecosystem');
    18→
    19→let _bridge = null;  // 싱글턴
    20→
    21→class PluginBridge {
    22→  constructor() {
    23→    this._ready    = false;
    24→    this._loader   = null;
    25→    this._stdlib   = null;
    26→    this._nodeDefs = [];   // NODE_DEF 배열
    27→    this._codeGenMap = {}; // type → codeGen fn
    28→    this._errors   = [];
    29→  }
    30→
    31→  // ── 초기화 ────────────────────────────────────────────────
    32→
    33→  /**
    34→   * 플러그인 시스템을 초기화합니다.
    35→   * 서버 시작 시 1회 호출.
    36→   */
    37→  init() {
    38→    if (this._ready) return this;
    39→
    40→    try {
    41→      const { PluginLoader }   = require(path.join(ECOSYSTEM_PATH, 'plugin/plugin-loader'));
    42→      const { PluginRegistry } = require(path.join(ECOSYSTEM_PATH, 'plugin/plugin-registry'));
    43→      const stdlib             = require(path.join(ECOSYSTEM_PATH, 'stdlib/index'));
    44→      const freewireStdlib     = require(path.join(ECOSYSTEM_PATH, 'plugins/freewire-stdlib'));
    45→
    46→      this._stdlib = stdlib;
    47→
    48→      const registry = new PluginRegistry();
    49→      registry.register(freewireStdlib);
    50→
    51→      this._loader = new PluginLoader({ registry, stdlib });
    52→      this._loader
    53→        .on('log',    ({ plugin, msg }) => console.log(`[Plugin:${plugin}] ${msg}`))
    54→        .on('warn',   ({ plugin, msg }) => console.warn(`[Plugin:${plugin}] ⚠ ${msg}`))
    55→        .on('loaded', ({ plugin })      => console.log(`[Plugin] ✓ ${plugin} 로드됨`));
    56→
    57→      this._loader.load('freewire-stdlib');
    58→
    59→      // freewire 확장 추출
    60→      const entry  = this._loader.getLoaded('freewire-stdlib');
    61→      const fw     = entry?.plugin?.provides?.freewire;
    62→
    63→      if (fw) {
    64→        this._nodeDefs = fw.nodeDefs || [];
    65→        // codeGenMap 빌드
    66→        for (const def of this._nodeDefs) {
    67→          if (def.codeGen) this._codeGenMap[def.type] = def.codeGen;
    68→        }
    69→        this._paletteCategory = fw.palette;
    70→        this._createNode      = fw.createNode.bind(fw);
    71→      }
    72→
    73→      this._ready = true;
    74→      console.log(`[PluginBridge] 초기화 완료 — stdlib 노드 ${this._nodeDefs.length}개`);
    75→
    76→    } catch (e) {
    77→      this._errors.push(e.message);
    78→      console.warn(`[PluginBridge] 초기화 실패 (ecosystem 없음): ${e.message}`);
    79→    }
    80→
    81→    return this;
    82→  }
    83→
    84→  // ── 조회 ──────────────────────────────────────────────────
    85→
    86→  get isReady()  { return this._ready; }
    87→  get nodeDefs() { return this._nodeDefs; }
    88→  get errors()   { return this._errors; }
    89→
    90→  /**
    91→   * /api/nodes 응답에 포함할 stdlib 팔레트 카테고리 반환
    92→   * @returns {object|null}
    93→   */
    94→  getPaletteCategory() {
    95→    if (!this._ready || !this._paletteCategory) return null;
    96→
    97→    return {
    98→      label:  this._paletteCategory.label,
    99→      color:  this._paletteCategory.color,
   100→      icon:   this._paletteCategory.icon,
   101→      subtypes: this._nodeDefs.map(d => ({
   102→        id:    d.type,
   103→        label: d.label,
   104→        color: d.color,
   105→      })),
   106→    };
   107→  }
   108→
   109→  /**
   110→   * 주어진 노드가 stdlib 노드인지 확인
   111→   * @param {object} node
   112→   * @returns {boolean}
   113→   */
   114→  isStdlibNode(node) {
   115→    return typeof node?.stdlibFn === 'string' ||
   116→           (typeof node?.type === 'string' && node.type.startsWith('stdlib:'));
   117→  }
   118→
   119→  /**
   120→   * stdlib 노드의 .free script 코드 생성
   121→   * @param {object} node — FreeWire 노드 JSON
   122→   * @returns {string}
   123→   */
   124→  codeGenNode(node) {
   125→    if (!this._ready) return `/* PluginBridge not ready */`;
   126→
   127→    // stdlibFn 기준으로 type 결정
   128→    const type = node.stdlibFn
   129→      ? `stdlib:${node.stdlibFn}`
   130→      : node.type;
   131→
   132→    const codeGen = this._codeGenMap[type];
   133→    if (!codeGen) return `/* stdlib codeGen 없음: ${type} */`;
   134→    return codeGen(node);
   135→  }
   136→
   137→  /**
   138→   * stdlib 노드 인스턴스 생성
   139→   * @param {string} type  — 예: 'stdlib:math.clamp'
   140→   * @param {string} id
   141→   * @param {object} opts
   142→   * @returns {object} FreeWire 노드 JSON
   143→   */
   144→  createNode(type, id, opts = {}) {
   145→    if (!this._ready || !this._createNode) {
   146→      throw new Error(`PluginBridge가 초기화되지 않았습니다`);
   147→    }
   148→    return this._createNode(type, id, opts);
   149→  }
   150→}
   151→
   152→// ── 싱글턴 ──────────────────────────────────────────────────
   153→
   154→function getBridge() {
   155→  if (!_bridge) {
   156→    _bridge = new PluginBridge();
   157→    _bridge.init();
   158→  }
   159→  return _bridge;
   160→}
   161→
   162→module.exports = { PluginBridge, getBridge };
   163→

