     1→/**
     2→ * FreeWire - 브라우저 실행 엔진 (Node.js 서버사이드 + 브라우저 공용)
     3→ * .free 코드를 파싱 → HTML/CSS/JS 변환 → 실시간 실행
     4→ * WASM 없이 순수 JS로 동작하지만 WASM Bridge 인터페이스 제공
     5→ */
     6→
     7→// ─── FreeLang Light 인라인 파서 ─────────────────────────────────
     8→class FreeLangParser {
     9→  constructor() { this.reset(); }
    10→
    11→  reset() {
    12→    this.props   = {};
    13→    this.style   = '';
    14→    this.script  = '';
    15→    this.markup  = '';
    16→    this.name    = 'Component';
    17→  }
    18→
    19→  parse(code) {
    20→    this.reset();
    21→    if (typeof code !== 'string') return this;
    22→
    23→    // 컴포넌트 이름 추출
    24→    const nameMatch = code.match(/component\s+(\w+)/);
    25→    if (nameMatch) this.name = nameMatch[1];
    26→
    27→    // 섹션 추출 (중첩 {} 지원)
    28→    this.props  = this._extractProps(code);
    29→    this.style  = this._extractBlock(code, 'style');
    30→    this.script = this._extractBlock(code, 'script');
    31→    this.markup = this._extractBlock(code, 'markup');
    32→
    33→    return this;
    34→  }
    35→
    36→  _extractBlock(code, keyword) {
    37→    const re = new RegExp(`\\b${keyword}\\s*\\{`);
    38→    const m  = re.exec(code);
    39→    if (!m) return '';
    40→    let depth = 1, i = m.index + m[0].length;
    41→    const start = i;
    42→    while (i < code.length && depth > 0) {
    43→      if (code[i] === '{') depth++;
    44→      else if (code[i] === '}') depth--;
    45→      i++;
    46→    }
    47→    return code.slice(start, i - 1).trim();
    48→  }
    49→
    50→  _extractProps(code) {
    51→    const block = this._extractBlock(code, 'props');
    52→    const props = {};
    53→    if (!block) return props;
    54→    const lines = block.split('\n').map(l => l.trim()).filter(Boolean);
    55→    lines.forEach(line => {
    56→      const m = line.match(/^(\w+)\s*:\s*\w+\s*(?:=\s*(.+?))?;?\s*$/);
    57→      if (m) props[m[1]] = (m[2] || '').replace(/['"]/g, '').replace(/;$/, '').trim();
    58→    });
    59→    return props;
    60→  }
    61→}
    62→
    63→// ─── CSS 컴파일러 ────────────────────────────────────────────────
    64→class CSSCompiler {
    65→  compile(styleBlock) {
    66→    if (!styleBlock || !styleBlock.trim()) return '';
    67→    return styleBlock
    68→      // HTML 태그 인젝션 방지 (<script>, <style> 등 제거)
    69→      .replace(/<[^>]*>/g, '')
    70→      .replace(/([a-z])([A-Z])/g, '$1-$2')
    71→      .toLowerCase()
    72→      .trim();
    73→  }
    74→}
    75→
    76→// ─── JS 컴파일러 ─────────────────────────────────────────────────
    77→class JSCompiler {
    78→  compile(scriptBlock, componentName) {
    79→    if (!scriptBlock || !scriptBlock.trim()) return '';
    80→
    81→    const lines = scriptBlock.split('\n').map(l => l.trim()).filter(Boolean);
    82→    const out   = [];
    83→
    84→    out.push(`/* FreeWire: ${componentName} */`); // eslint-disable-line
    85→    out.push('(function(fw) {');
    86→    out.push('  "use strict";');
    87→    out.push('  fw._vars = {};');   // 변수 레지스트리 (eval 대체)
    88→    out.push('  fw._funcs = {};');  // 함수 레지스트리 (eval 대체)
    89→
    90→    const stateVars = [];
    91→    const letVars   = [];
    92→
    93→    lines.forEach(line => {
    94→      // state setter 감지: function set_xxx(v) { xxx = v; }
    95→      const setterMatch = line.match(/^function\s+set_(\w+)\(/);
    96→      if (setterMatch) stateVars.push(setterMatch[1]);
    97→
    98→      // let/const 선언 추적
    99→      const letMatch = line.match(/^(?:let|const)\s+(\w+)\s*=/);
   100→      if (letMatch) letVars.push(letMatch[1]);
   101→
   102→      // 함수 선언 추적
   103→      const funcMatch = line.match(/^function\s+(\w+)\s*\(/);
   104→
   105→      out.push('  ' + line);
   106→
   107→      // 함수 선언 직후 레지스트리에 등록
   108→      if (funcMatch) {
   109→        out.push(`  fw._funcs["${funcMatch[1]}"] = ${funcMatch[1]};`);
   110→      }
   111→    });
   112→
   113→    // 반응형 DOM 업데이트 (eval 제거 → fw._vars 딕셔너리 룩업)
   114→    out.push('');
   115→    out.push('  // 반응형 DOM 업데이트');
   116→    out.push('  function __fw_update() {');
   117→    // 모든 추적 변수를 현재 스코프에서 갱신
   118→    letVars.forEach(v => {
   119→      out.push(`    try { fw._vars["${v}"] = ${v}; } catch(e) {}`);
   120→    });
   121→    out.push('    var els = document.querySelectorAll("[data-fw-bind]");');
   122→    out.push('    els.forEach(function(el) {');
   123→    out.push('      var key = el.getAttribute("data-fw-bind");');
   124→    out.push('      el.textContent = key in fw._vars ? fw._vars[key] : "";');
   125→    out.push('    });');
   126→    out.push('  }');
   127→    out.push('');
   128→
   129→    // setter 오버라이드 (원본 setter 호출 후 __fw_update)
   130→    stateVars.forEach(v => {
   131→      out.push(`  var __orig_set_${v} = typeof set_${v} === "function" ? set_${v} : null;`);
   132→      out.push(`  set_${v} = function(v) { if (__orig_set_${v}) __orig_set_${v}(v); __fw_update(); };`);
   133→      out.push(`  fw._funcs["set_${v}"] = set_${v};`);
   134→    });
   135→
   136→    // 이벤트 바인딩 (eval 제거 → fw._funcs 딕셔너리 룩업)
   137→    out.push('');
   138→    out.push('  document.addEventListener("DOMContentLoaded", function() {');
   139→    out.push('    __fw_update();');
   140→    out.push('    // 버튼 이벤트 자동 바인딩');
   141→    out.push('    document.querySelectorAll("[data-fw-action]").forEach(function(el) {');
   142→    out.push('      var action = el.getAttribute("data-fw-action");');
   143→    out.push('      el.addEventListener("click", function() {');
   144→    out.push('        var fn = fw._funcs[action]; if (fn) { try { fn(); } catch(e) { console.warn("FW:", e); } }');
   145→    out.push('        __fw_update();');
   146→    out.push('      });');
   147→    out.push('    });');
   148→    out.push('  });');
   149→    out.push('})({});');
   150→
   151→    return out.join('\n');
   152→  }
   153→}
   154→
   155→// ─── HTML 컴파일러 ───────────────────────────────────────────────
   156→class HTMLCompiler {
   157→  compile(markupBlock) {
   158→    if (!markupBlock || !markupBlock.trim()) return '';
   159→
   160→    return markupBlock
   161→      .replace(/\bmarkup\s*\{/g, '')
   162→      .replace(/^\s*\}\s*$/gm, '')
   163→      // {{변수}} → data-fw-bind 속성
   164→      .replace(/\{\{(\w+)\}\}/g, '<span data-fw-bind="$1">$1</span>')
   165→      // 버튼 클릭 함수 자동 감지: onclick="xxx()" → data-fw-action
   166→      .replace(/onclick="(\w+)\(\)"/g, 'data-fw-action="$1"')
   167→      .replace(/\n{3,}/g, '\n\n')
   168→      .trim();
   169→  }
   170→}
   171→
   172→// ─── 메인 실행 엔진 ──────────────────────────────────────────────
   173→class BrowserExecutor {
   174→  constructor() {
   175→    this.parser  = new FreeLangParser();
   176→    this.css     = new CSSCompiler();
   177→    this.js      = new JSCompiler();
   178→    this.html    = new HTMLCompiler();
   179→    this.history = [];
   180→  }
   181→
   182→  /**
   183→   * .free 코드 → { html, css, js, name, stats }
   184→   */
   185→  execute(freeCode) {
   186→    if (typeof freeCode !== 'string' || !freeCode.trim()) {
   187→      return { name: 'Component', html: '', css: '', js: '', props: {}, stats: { parseMs: 0, htmlBytes: 0, cssBytes: 0, jsBytes: 0, hasStyle: false, hasScript: false } };
   188→    }
   189→    const start = Date.now();
   190→    const parsed = this.parser.parse(freeCode);
   191→
   192→    const css  = this.css.compile(parsed.style);
   193→    const js   = this.js.compile(parsed.script, parsed.name);
   194→    const html = this.html.compile(parsed.markup);
   195→
   196→    const result = {
   197→      name:  parsed.name,
   198→      html,  css, js,
   199→      props: parsed.props,
   200→      stats: {
   201→        parseMs:   Date.now() - start,
   202→        htmlBytes: html.length,
   203→        cssBytes:  css.length,
   204→        jsBytes:   js.length,
   205→        hasStyle:  css.length > 0,
   206→        hasScript: js.length > 0,
   207→      },
   208→    };
   209→
   210→    this.history.push({ code: freeCode, result, ts: Date.now() });
   211→    if (this.history.length > 50) this.history.shift();
   212→
   213→    return result;
   214→  }
   215→
   216→  /**
   217→   * 전체 미리보기 HTML 생성 (iframe srcdoc용)
   218→   */
   219→  buildPreviewHTML(result) {
   220→    if (!result || typeof result !== 'object') {
   221→      result = { html: '', css: '', js: '' };
   222→    }
   223→    // CSS 인젝션 방어: </style> 태그 이스케이프
   224→    const safeCss = (result.css || '').replace(/<\/style>/gi, '<\\/style>');
   225→    const safeJs  = (result.js  || '');
   226→    const safeHtml = (result.html || '<p style="color:#9ca3af">내용 없음</p>');
   227→    return `<!DOCTYPE html>
   228→<html lang="ko">
   229→<head>
   230→<meta charset="UTF-8">
   231→<style>
   232→  * { box-sizing: border-box; margin: 0; padding: 0; }
   233→  body { font-family: system-ui, sans-serif; padding: 20px; background: #f8fafc; }
   234→  button { cursor: pointer; padding: 8px 16px; border: none; border-radius: 6px; font-size: 14px; }
   235→  button.primary   { background: #6366f1; color: #fff; }
   236→  button.secondary { background: #e2e8f0; color: #374151; }
   237→  button.ghost     { background: transparent; border: 1px solid #d1d5db; color: #374151; }
   238→  input { padding: 8px 12px; border: 1px solid #d1d5db; border-radius: 6px; font-size: 14px; width: 100%; }
   239→  .card { background: #fff; border-radius: 12px; padding: 20px; box-shadow: 0 2px 8px rgba(0,0,0,.08); }
   240→  .card.glass { background: rgba(255,255,255,.2); backdrop-filter: blur(10px); border: 1px solid rgba(255,255,255,.3); }
   241→  .container { display: flex; }
   242→  .container.column { flex-direction: column; }
   243→  .container.row    { flex-direction: row; }
   244→  .freewire-badge {
   245→    position: fixed; bottom: 8px; right: 8px;
   246→    background: #6366f1; color: #fff;
   247→    padding: 3px 8px; border-radius: 999px; font-size: 11px; opacity: .8;
   248→  }
   249→  ${safeCss}
   250→</style>
   251→</head>
   252→<body>
   253→<div id="fw-root">${safeHtml}</div>
   254→<div class="freewire-badge">⚡ FreeWire</div>
   255→<script>${safeJs}</script>
   256→</body>
   257→</html>`;
   258→  }
   259→
   260→  /** 마지막 실행 결과 */
   261→  lastResult() { return this.history[this.history.length - 1]?.result || null; }
   262→
   263→  /** 히스토리 초기화 */
   264→  clearHistory() { this.history = []; }
   265→}
   266→
   267→// ─── WASM Bridge 인터페이스 (미래 확장용) ───────────────────────
   268→const WASMBridge = {
   269→  _executor: new BrowserExecutor(),
   270→  _ready: true,
   271→
   272→  /** WASM 준비 여부 */
   273→  isReady() { return this._ready; },
   274→
   275→  /** .free 코드 컴파일 */
   276→  compile(freeCode) {
   277→    if (!this._ready) throw new Error('WASMBridge not ready');
   278→    return this._executor.execute(freeCode);
   279→  },
   280→
   281→  /** 미리보기 HTML 생성 */
   282→  preview(freeCode) {
   283→    if (!this._ready) throw new Error('WASMBridge not ready');
   284→    const result = this.compile(freeCode);
   285→    return this._executor.buildPreviewHTML(result);
   286→  },
   287→
   288→  /** 히스토리 */
   289→  history() { return this._executor.history; },
   290→};
   291→
   292→// Node.js / 브라우저 공용 export
   293→if (typeof module !== 'undefined') {
   294→  module.exports = { BrowserExecutor, WASMBridge, FreeLangParser, CSSCompiler, JSCompiler, HTMLCompiler };
   295→} else {
   296→  window.FreeWireWASM = WASMBridge;
   297→  window.BrowserExecutor = BrowserExecutor;
   298→}
