```

**After**:
```js
const VALID_SEVERITIES = new Set(['error', 'warning']);

class ContractViolation {
  constructor({ nodeId, nodeLabel, type, fact, message, severity, repairHint }) {
    this.nodeId    = nodeId;
    this.nodeLabel = nodeLabel;
    this.type      = type;
    this.fact      = fact;
    this.message   = message;
    // 유효하지 않은 severity는 'error'로 fallback
    this.severity  = VALID_SEVERITIES.has(severity) ? severity : 'error';
    this.repairHint= repairHint;
  }
```

