 * HTML 속성값 이스케이프 (XSS 방지)
 * 사용처: href="...", class="...", type="..." 등 따옴표 안 속성값
 * 따옴표 탈출(" → &quot;, ' → &#x27;)을 포함하여 속성 경계 탈출 방지
 * @param {*} val
 * @returns {string}
 */
function escapeAttr(val) { ... }

